import { useState, useEffect } from "react";

function PostForm({ token, onPostAdded, categoryId }) {
    const [title, setTitle] = useState("");
    const [content, setContent] = useState("");
    const [error, setError] = useState("");
    const [loading, setLoading] = useState(false);
    const [selectedCat, setSelectedCat] = useState(categoryId || 1);
    const [categories, setCategories] = useState([]);

    useEffect(() => {
        if (categoryId) setSelectedCat(categoryId);
    }, [categoryId]);

    useEffect(() => {
        fetch("http://localhost:5000/api/categories")
            .then(res => res.json())
            .then(data => setCategories(data))
            .catch(err => console.error(err));
    }, []);

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!title || !content) { setError("Заповніть всі поля"); return; }
        setLoading(true);

        try {
            const res = await fetch("http://localhost:5000/api/posts", {
                method: "POST",
                headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
                body: JSON.stringify({ title, content, category_id: selectedCat }),
            });

            const data = await res.json();
            if (!res.ok) setError(data.message || "Помилка при створенні поста");
            else {
                setTitle(""); setContent(""); setError("");
                if (onPostAdded) onPostAdded();
            }
        } catch (err) {
            console.error(err);
            setError("Помилка при запиті до сервера");
        } finally { setLoading(false); }
    };

    return (
        <div className="card-gradient rounded-2xl p-6 shadow-xl">
            <h3 className="text-xl font-bold gradient-text mb-4">Створити пост</h3>
            {error && <div className="mb-4 p-3 bg-red-50 border-l-4 border-red-500 rounded-lg"><p className="text-red-700 text-sm">{error}</p></div>}

            <form onSubmit={handleSubmit} className="space-y-4">
                <input type="text" placeholder="Заголовок..." value={title} onChange={(e) => setTitle(e.target.value)} className="input-field" />
                <textarea placeholder="Вміст..." value={content} onChange={(e) => setContent(e.target.value)} rows={4} className="input-field resize-none" />

                <select value={selectedCat} onChange={(e) => setSelectedCat(e.target.value)} className="input-field">
                    {categories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
                </select>

                <button type="submit" disabled={loading} className="btn-primary w-full disabled:opacity-50">
                    {loading ? "Публікуємо..." : "Опублікувати"}
                </button>
            </form>
        </div>
    );
}

export default PostForm;
